/// Role: verify owned BGRA history, caret cadence, sharp glyph guards and delivery retries with real CoreVideo storage [D254,D266,#146].
import CoreVideo
import Foundation

@main struct FramePixelsTest {
    static func expect(_ value: Bool, _ label: String) {
        if !value { fputs("FAIL \(label)\n", stderr); exit(1) }
    }
    static func pixel(_ width: Int, _ height: Int, format: OSType = kCVPixelFormatType_32BGRA) -> CVPixelBuffer {
        var result: CVPixelBuffer?
        let attrs = [kCVPixelBufferBytesPerRowAlignmentKey as String: 128] as CFDictionary
        expect(CVPixelBufferCreate(kCFAllocatorDefault, width, height, format, attrs, &result) == kCVReturnSuccess, "real buffer allocation")
        return result!
    }
    static func fill(_ pixel: CVPixelBuffer, _ byte: UInt8, padding: UInt8 = 0) {
        expect(CVPixelBufferLockBaseAddress(pixel, []) == kCVReturnSuccess, "write lock")
        defer { CVPixelBufferUnlockBaseAddress(pixel, []) }
        let base = CVPixelBufferGetBaseAddress(pixel)!
        let stride = CVPixelBufferGetBytesPerRow(pixel), rowBytes = CVPixelBufferGetWidth(pixel) * 4
        for y in 0..<CVPixelBufferGetHeight(pixel) {
            base.advanced(by: y * stride).initializeMemory(as: UInt8.self, repeating: padding, count: stride)
            base.advanced(by: y * stride).initializeMemory(as: UInt8.self, repeating: byte, count: rowBytes)
        }
    }
    static func paint(_ pixel: CVPixelBuffer, x: Int, y: Int, width: Int, height: Int, byte: UInt8) {
        expect(CVPixelBufferLockBaseAddress(pixel, []) == kCVReturnSuccess, "damage write lock")
        defer { CVPixelBufferUnlockBaseAddress(pixel, []) }
        let base = CVPixelBufferGetBaseAddress(pixel)!
        let stride = CVPixelBufferGetBytesPerRow(pixel)
        for row in y..<(y + height) {
            for column in x..<(x + width) {
                base.advanced(by: row * stride + column * 4).initializeMemory(as: UInt8.self, repeating: byte, count: 4)
            }
        }
    }
    static func paintSparse(_ pixel: CVPixelBuffer, x: Int, y: Int, width: Int, height: Int, byte: UInt8) {
        expect(CVPixelBufferLockBaseAddress(pixel, []) == kCVReturnSuccess, "sparse damage write lock")
        defer { CVPixelBufferUnlockBaseAddress(pixel, []) }
        let base = CVPixelBufferGetBaseAddress(pixel)!
        let stride = CVPixelBufferGetBytesPerRow(pixel)
        for row in 0..<height {
            for column in 0..<width where (row * width + column).isMultiple(of: 2) || (row == height - 1 && column == width - 1) {
                base.advanced(by: (y + row) * stride + (x + column) * 4).initializeMemory(as: UInt8.self, repeating: byte, count: 4)
            }
        }
    }
    static func main() {
        let damageHistory = FramePixels(), surface = pixel(96, 48)
        fill(surface, 47)
        expect(damageHistory.prepare(surface, at: 0), "first damage picture")
        expect(damageHistory.damageKind == .content, "first picture is conservative content")
        damageHistory.delivered()
        expect(!damageHistory.prepare(surface, at: 0.05), "identical damage picture")
        expect(damageHistory.damageKind == .unchanged, "identical picture has no damage")
        damageHistory.delivered()

        let measuredBlink = FramePixels(), measuredSurface = pixel(96, 48)
        fill(measuredSurface, 47)
        expect(measuredBlink.prepare(measuredSurface, at: 0), "first measured blink picture")
        measuredBlink.delivered()
        paint(measuredSurface, x: 35, y: 15, width: 8, height: 18, byte: 199)
        expect(measuredBlink.prepare(measuredSurface, at: 0.1), "first measured caret change")
        expect(measuredBlink.damageKind == .content, "first measured caret change keeps a sharp refresh")
        measuredBlink.delivered()
        paint(measuredSurface, x: 35, y: 15, width: 8, height: 19, byte: 200)
        expect(measuredBlink.prepare(measuredSurface, at: 0.135), "rapid measured fade change")
        expect(measuredBlink.damageKind == .content, "rapid fade cannot establish blink cadence")
        measuredBlink.delivered()
        paint(measuredSurface, x: 35, y: 15, width: 8, height: 19, byte: 201)
        expect(measuredBlink.prepare(measuredSurface, at: 0.685), "same measured footprint recurs at blink cadence")
        expect(measuredBlink.damageKind == .caret, "repeated 8-by-19 caret damage uses a delta")
        measuredBlink.delivered()
        paint(measuredSurface, x: 35, y: 15, width: 8, height: 18, byte: 202)
        expect(measuredBlink.prepare(measuredSurface, at: 0.72), "measured caret fade changes quickly")
        expect(measuredBlink.damageKind == .caret, "fast fade within the recognized footprint stays a delta")
        measuredBlink.delivered()
        paint(measuredSurface, x: 34, y: 16, width: 9, height: 10, byte: 203)
        expect(measuredBlink.prepare(measuredSurface, at: 0.755), "measured partial caret fade changes")
        expect(measuredBlink.damageBounds == PixelDamageBounds(x: 34, y: 16, width: 9, height: 10)
            && measuredBlink.changedPixels == 90 && measuredBlink.damageBoundsComplete,
            "partial fade scan retains its complete measured bounds")
        expect(measuredBlink.damageKind == .caret, "nearby 9-by-10 fade remains within the recognized caret cluster")
        measuredBlink.delivered()
        paintSparse(measuredSurface, x: 35, y: 12, width: 9, height: 20, byte: 204)
        expect(measuredBlink.prepare(measuredSurface, at: 0.8), "measured fade footprint shifts three pixels vertically")
        expect(measuredBlink.damageBounds == PixelDamageBounds(x: 35, y: 12, width: 9, height: 20)
            && measuredBlink.changedPixels <= 160 && measuredBlink.damageBoundsComplete,
            "sparse fade scan retains its complete measured bounds")
        expect(measuredBlink.damageKind == .caret, "nearby 9-by-20 partial fade remains in the caret cluster")
        measuredBlink.delivered()
        paint(measuredSurface, x: 35, y: 15, width: 8, height: 19, byte: 204)
        expect(measuredBlink.prepare(measuredSurface, at: 1.235), "measured caret footprint repeats after its fade cluster")
        expect(measuredBlink.damageKind == .caret, "nearby fade changes do not reset the cadence anchor")
        measuredBlink.delivered()
        paint(measuredSurface, x: 35, y: 15, width: 8, height: 19, byte: 205)
        expect(measuredBlink.prepare(measuredSurface, at: 2.835), "expired measured blink changes again")
        expect(measuredBlink.damageKind == .content, "expired cadence restores sharp refresh")
        measuredBlink.delivered()
        paint(measuredSurface, x: 35, y: 15, width: 8, height: 19, byte: 206)
        expect(measuredBlink.prepare(measuredSurface, at: 3.385), "measured blink cadence is re-established")
        expect(measuredBlink.damageKind == .caret, "repeated cadence can be recognized again")
        measuredBlink.delivered()
        paint(measuredSurface, x: 36, y: 15, width: 7, height: 19, byte: 207)
        expect(measuredBlink.prepare(measuredSurface, at: 3.42), "glyph footprint changes")
        expect(measuredBlink.damageKind == .content, "a width-seven glyph resets caret recognition")
        measuredBlink.delivered()

        let scaledBlink = FramePixels(), scaledSurface = pixel(96, 48)
        fill(scaledSurface, 47)
        expect(scaledBlink.prepare(scaledSurface, at: 0), "first scaled caret picture")
        scaledBlink.delivered()
        paint(scaledSurface, x: 60, y: 15, width: 7, height: 17, byte: 210)
        expect(scaledBlink.prepare(scaledSurface, at: 0.1), "first seven-pixel caret anchor")
        expect(scaledBlink.damageKind == .content, "first scaled caret change remains conservative")
        scaledBlink.delivered()
        paint(scaledSurface, x: 60, y: 15, width: 8, height: 17, byte: 211)
        expect(scaledBlink.prepare(scaledSurface, at: 0.135), "eight-pixel fade within the same anchor")
        expect(scaledBlink.damageKind == .content, "fast width variation cannot establish cadence")
        scaledBlink.delivered()
        paint(scaledSurface, x: 60, y: 15, width: 9, height: 17, byte: 212)
        expect(scaledBlink.prepare(scaledSurface, at: 0.17), "nine-pixel fade adjacent to the anchor")
        expect(scaledBlink.damageKind == .content, "unconfirmed adjacent fade remains conservative")
        scaledBlink.delivered()
        paint(scaledSurface, x: 60, y: 15, width: 7, height: 17, byte: 213)
        expect(scaledBlink.prepare(scaledSurface, at: 0.685), "seven-pixel anchor recurs at blink cadence")
        expect(scaledBlink.damageKind == .caret, "seven and eight-pixel anchors share measured cadence")
        scaledBlink.delivered()
        paint(scaledSurface, x: 60, y: 15, width: 9, height: 17, byte: 214)
        expect(scaledBlink.prepare(scaledSurface, at: 0.72), "nine-pixel fade follows scaled anchor")
        expect(scaledBlink.damageKind == .caret, "one-pixel anchor variation plus one fade pixel stays caret")
        scaledBlink.delivered()

        let ninePixelBlink = FramePixels(), ninePixelSurface = pixel(96, 48)
        fill(ninePixelSurface, 47)
        expect(ninePixelBlink.prepare(ninePixelSurface, at: 0), "first nine-pixel helper-managed picture")
        ninePixelBlink.delivered()
        paint(ninePixelSurface, x: 45, y: 14, width: 9, height: 17, byte: 210)
        expect(ninePixelBlink.prepare(ninePixelSurface, at: 0.1), "first measured nine-pixel caret anchor")
        expect(ninePixelBlink.damageKind == .content, "first nine-pixel caret anchor remains conservative")
        ninePixelBlink.delivered()
        paint(ninePixelSurface, x: 45, y: 14, width: 9, height: 17, byte: 211)
        expect(ninePixelBlink.prepare(ninePixelSurface, at: 0.653), "measured nine-pixel anchor recurs at blink cadence")
        expect(ninePixelBlink.damageKind == .caret, "recurring nine-pixel caret anchor uses a delta")
        ninePixelBlink.delivered()
        paint(ninePixelSurface, x: 45, y: 14, width: 9, height: 17, byte: 212)
        paint(ninePixelSurface, x: 45, y: 14, width: 9, height: 1, byte: 211)
        paint(ninePixelSurface, x: 45, y: 30, width: 9, height: 1, byte: 211)
        expect(ninePixelBlink.prepare(ninePixelSurface, at: 0.688), "measured nine-by-fifteen fade follows anchor")
        expect(ninePixelBlink.damageBounds == PixelDamageBounds(x: 45, y: 15, width: 9, height: 15)
            && ninePixelBlink.damageKind == .caret, "measured nine-by-fifteen fade stays a delta")
        ninePixelBlink.delivered()
        paint(ninePixelSurface, x: 45, y: 14, width: 9, height: 17, byte: 213)
        paint(ninePixelSurface, x: 45, y: 14, width: 9, height: 1, byte: 211)
        expect(ninePixelBlink.prepare(ninePixelSurface, at: 0.723), "measured nine-by-sixteen fade follows anchor")
        expect(ninePixelBlink.damageBounds == PixelDamageBounds(x: 45, y: 15, width: 9, height: 16)
            && ninePixelBlink.damageKind == .caret, "measured nine-by-sixteen fade stays a delta")
        ninePixelBlink.delivered()
        paint(ninePixelSurface, x: 46, y: 16, width: 7, height: 13, byte: 214)
        expect(ninePixelBlink.prepare(ninePixelSurface, at: 0.758), "nearby nine-by-thirteen glyph changes")
        expect(ninePixelBlink.damageBounds == PixelDamageBounds(x: 46, y: 16, width: 7, height: 13)
            && ninePixelBlink.damageKind == .content, "unseen nearby glyph keeps a sharp update")
        ninePixelBlink.delivered()

        let shiftedBlink = FramePixels(), shiftedSurface = pixel(96, 48)
        fill(shiftedSurface, 47)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0), "first shifted caret picture")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 60, y: 15, width: 7, height: 16, byte: 210)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.443), "first shifted seven-pixel anchor")
        expect(shiftedBlink.damageKind == .content, "shifted caret anchor remains conservative at first")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 59, y: 18, width: 8, height: 13, byte: 211)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.477), "shifted eight-pixel anchor variation")
        expect(shiftedBlink.damageKind == .content, "fast shifted anchor variation cannot establish cadence")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 58, y: 15, width: 10, height: 13, byte: 212)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.511), "measured ten-pixel caret fade")
        expect(shiftedBlink.damageBounds == PixelDamageBounds(x: 58, y: 15, width: 10, height: 13)
            && shiftedBlink.changedPixels == 130 && shiftedBlink.damageBoundsComplete,
            "measured ten-pixel fade stays inside the bounded complete scan")
        expect(shiftedBlink.damageKind == .content, "ten-pixel fade stays conservative before cadence")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 58, y: 16, width: 9, height: 15, byte: 213)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.544), "measured shifted nine-pixel fade")
        expect(shiftedBlink.damageKind == .content, "unconfirmed shifted fade remains conservative")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 58, y: 16, width: 9, height: 15, byte: 214)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.795), "measured shifted fade repeats before anchor")
        expect(shiftedBlink.damageKind == .content, "fade repetition alone does not establish cadence")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 58, y: 15, width: 10, height: 13, byte: 215)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.829), "measured ten-pixel fade repeats")
        expect(shiftedBlink.damageKind == .content, "ten-pixel fade remains conservative before anchor cadence")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 59, y: 18, width: 8, height: 13, byte: 216)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.859), "measured eight-pixel anchor recurs")
        expect(shiftedBlink.damageKind == .caret, "measured fades preserve the recurring anchor cadence")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 60, y: 15, width: 7, height: 16, byte: 217)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.892), "measured seven-pixel anchor variation recurs")
        expect(shiftedBlink.damageKind == .caret, "active shifted cadence spans seven and eight-pixel anchors")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 58, y: 15, width: 10, height: 13, byte: 218)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.926), "measured ten-pixel fade follows active cadence")
        expect(shiftedBlink.damageKind == .caret, "active cadence includes the measured ten-pixel fade")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 58, y: 16, width: 9, height: 15, byte: 219)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.960), "measured nine-pixel fade follows active cadence")
        expect(shiftedBlink.damageKind == .caret, "active cadence includes the measured nine-pixel fade")
        shiftedBlink.delivered()
        paint(shiftedSurface, x: 57, y: 15, width: 11, height: 13, byte: 220)
        expect(shiftedBlink.prepare(shiftedSurface, at: 0.994), "wider neighboring content damage")
        expect(shiftedBlink.damageKind == .content && !shiftedBlink.damageBoundsComplete,
            "eleven-pixel content remains outside the bounded caret scan")
        shiftedBlink.delivered()

        paint(measuredSurface, x: 0, y: 0, width: 96, height: 48, byte: 199)
        expect(measuredBlink.prepare(measuredSurface, at: 3.455), "scroll pixels change")
        expect(measuredBlink.damageKind == .content, "full-window pixel damage remains content")

        let history = FramePixels(), a = pixel(17, 9), b = pixel(17, 9)
        fill(a, 31); fill(b, 31, padding: 199)
        expect(history.prepare(a), "first picture")
        history.dropped()
        expect(history.prepare(a), "unconfirmed picture must retry")
        history.delivered()
        expect(!history.prepare(b), "padding is not content")
        history.dropped()
        expect(!history.prepare(a), "dropped refresh retains delivered history")
        fill(a, 47)
        expect(history.prepare(a), "reused object changed")
        // The original input may be reused after submission. History owns bytes.
        fill(a, 31)
        history.delivered()
        expect(history.prepare(a), "history is independent of reused buffer")
        history.delivered()
        expect(CVPixelBufferLockBaseAddress(a, []) == kCVReturnSuccess, "last-pixel write lock")
        let last = CVPixelBufferGetBaseAddress(a)!.advanced(by: (CVPixelBufferGetHeight(a) - 1) * CVPixelBufferGetBytesPerRow(a) + (CVPixelBufferGetWidth(a) - 1) * 4 + 3)
        last.storeBytes(of: UInt8(7), as: UInt8.self)
        CVPixelBufferUnlockBaseAddress(a, [])
        expect(history.prepare(a), "last-row alpha is picture content")
        history.delivered()
        let resized = pixel(9, 17); fill(resized, 31)
        expect(history.prepare(resized), "equal byte count with different dimensions")
        history.delivered()
        let planar = pixel(16, 16, format: kCVPixelFormatType_420YpCbCr8BiPlanarVideoRange)
        expect(history.prepare(planar), "unknown format is conservative")
        history.delivered()
        expect(history.prepare(resized), "unknown format invalidates history")
        history.delivered()
        let oversized = pixel(4096, 1025)
        expect(history.prepare(oversized), "oversized input is conservative")
        history.delivered()
        expect(history.prepare(resized), "oversized input invalidates history")
        history.delivered(); history.reset()
        expect(history.prepare(resized), "reset retires history")
        print("PASS exact BGRA history: padding, reused storage, last-row alpha, dimensions, raw drop, refresh drop, unknown format and reset")
    }
}
